using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using OneWay.Battle3D;
public static class BuildB2Slash {
 const string Dir="Assets/3DBattle/Boss2/";
 public static object Run(){if(Application.isPlaying)throw new Exception("Stop play first");var a=UnityEngine.Object.FindObjectsByType<Animator>(FindObjectsInactive.Include,FindObjectsSortMode.None).First(t=>t.name.StartsWith("Meshy_AI_lowpoly_paladin")&&t.gameObject.scene.name=="3DBattleScene");
 var source=AssetDatabase.LoadAssetAtPath<GameObject>(Dir+"Meshy_AI_symmetric_white_slash_3d_20261105_generate.fbx");var temp=UnityEngine.Object.Instantiate(source);temp.hideFlags=HideFlags.HideAndDontSave;var prefabRoot=new GameObject("B2WhiteSlash");prefabRoot.hideFlags=HideFlags.None;
 try{var filter=temp.GetComponentInChildren<MeshFilter>();var mesh=UnityEngine.Object.Instantiate(filter.sharedMesh);mesh.name="B2WhiteSlashMesh";var matrix=Matrix4x4.Rotate(Quaternion.Euler(0,90,90))*filter.transform.localToWorldMatrix;var vertices=mesh.vertices.Select(v=>matrix.MultiplyPoint3x4(v)).ToArray();var bounds=new Bounds(vertices[0],Vector3.zero);foreach(var v in vertices)bounds.Encapsulate(v);for(int i=0;i<vertices.Length;i++)vertices[i]=(vertices[i]-bounds.center)/bounds.size.y;mesh.vertices=vertices;mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,Dir+"B2WhiteSlashMesh.asset");
 var texture=new Texture2D(2,2,TextureFormat.RGBA32,false);texture.name="SlashSolidWhite";texture.SetPixels(new[]{Color.white,Color.white,Color.white,Color.white});texture.Apply();AssetDatabase.CreateAsset(texture,Dir+"SlashSolidWhite.asset");var mat=new Material(Shader.Find("Universal Render Pipeline/Unlit"));mat.name="B2SlashWhite";mat.SetTexture("_BaseMap",texture);mat.SetColor("_BaseColor",Color.white);mat.SetFloat("_Cull",0);AssetDatabase.CreateAsset(mat,Dir+"B2SlashWhite.mat");
 prefabRoot.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=prefabRoot.AddComponent<MeshRenderer>();renderer.sharedMaterial=mat;renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;renderer.receiveShadows=false;var prefab=PrefabUtility.SaveAsPrefabAsset(prefabRoot,Dir+"B2WhiteSlash.prefab");
 if(prefab==null)throw new Exception("Prefab save failed");var component=a.GetComponent<B2SwordSlash>();if(component==null)component=Undo.AddComponent<B2SwordSlash>(a.gameObject);Undo.RecordObject(component,"Connect B2 slash");component.boss=a.GetComponentInParent<BattleBoss>();component.body=a.GetComponentInChildren<SkinnedMeshRenderer>();component.swordGrip=a.GetComponentsInChildren<Transform>(true).Single(t=>t.name=="Holy Sword Grip");component.slashPrefab=prefab;component.heightMultiplier=2;component.travelSpeed=20;component.lifetime=2;
 var clip=a.runtimeAnimatorController.animationClips.Single();var events=AnimationUtility.GetAnimationEvents(clip).Where(e=>e.functionName!="EmitB2SwordSlash").ToList();events.Add(new AnimationEvent{functionName="EmitB2SwordSlash",time=44f/clip.frameRate});AnimationUtility.SetAnimationEvents(clip,events.ToArray());EditorUtility.SetDirty(component);EditorUtility.SetDirty(clip);PrefabUtility.RecordPrefabInstancePropertyModifications(component);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(a.gameObject.scene);
 return new{height=component.BossHeight,slashHeight=component.BossHeight*2,normalizedMeshHeight=mesh.bounds.size.y,eventFrame=44,clip=clip.name};
 }finally{UnityEngine.Object.DestroyImmediate(temp);UnityEngine.Object.DestroyImmediate(prefabRoot);}}
}

